SELECT AS period, COUNT(*) AS appointment_count, SUM(CASE WHEN status IN ('ARRIVED', 'COMPLETED') THEN 1 ELSE 0 END) AS arrived_count, SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelled_count FROM biz_appointment WHERE deleted = 0 AND appoint_time >= #{start} AND appoint_time < #{end}
AND store_id = #{storeId}
GROUP BY
ORDER BY period
